/**
 * The handler being defined. Set options on it at the top level of the file; define `Game.Play` to customise each instance.
 */
declare const Game: Game;
/**
 * Hub metadata. Written by hub.splitscreen.me when the handler is uploaded, and kept up to date there. Don't add or edit these lines yourself.
 */
declare const Hub: Hub;
/**
 * .NET `System` namespace (e.g. `System.IO.File.Copy`, `System.IO.Path.Combine`).
 */
declare const System: any;
/**
 * Imports a .NET namespace, e.g. `importNamespace("System.IO")`.
 */
declare function importNamespace(name: string): any;
/**
 * Per-instance context. Only available inside `Game.Play` and other callbacks.
 */
declare const Context: Context;
/**
 * The player whose instance is being set up. Only available inside `Game.Play` and other callbacks.
 */
declare const Player: PlayerInfo;
/**
 * All players of the session (`PlayerList.Count`). Only available inside callbacks.
 */
declare const PlayerList: DotNetList<PlayerInfo>;
/**
 * The running `GenericGameHandler`. Only available inside callbacks.
 */
declare const Handler: any;
/**
 * Proto Input runtime API (install hooks, toggle message filters). Only available inside callbacks such as `Game.ProtoInput.OnInputLocked`.
 */
declare const ProtoInput: ProtoInputRuntime;
